
/* ===== 100% OFFLINE BUNDLED LIBRARIES FOR KASIR SAAYA ===== */
(function(global) {
  'use strict';

  /* --- 1. Offline QRCode Generator (EMVCo QRIS & URL QR) --- */
  // Complete Reed-Solomon + QR Byte-Mode encoder (Versions 1 to 14, EC Level L/M)
  const QR_EXP = new Uint8Array(512);
  const QR_LOG = new Uint8Array(256);
  (function initGF() {
    let x = 1;
    for (let i = 0; i < 255; i++) {
      QR_EXP[i] = x;
      QR_LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11d;
    }
    for (let i = 255; i < 512; i++) QR_EXP[i] = QR_EXP[i - 255];
  })();

  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return QR_EXP[QR_LOG[a] + QR_LOG[b]];
  }

  function rsGeneratorPoly(ecLen) {
    let g = [1];
    for (let i = 0; i < ecLen; i++) {
      const next = new Array(g.length + 1).fill(0);
      const factor = QR_EXP[i];
      for (let j = 0; j < g.length; j++) {
        next[j] ^= g[j];
        next[j + 1] ^= gfMul(g[j], factor);
      }
      g = next;
    }
    return g;
  }

  function rsComputeEC(dataBytes, ecLen) {
    const gen = rsGeneratorPoly(ecLen);
    const res = new Uint8Array(ecLen);
    for (let i = 0; i < dataBytes.length; i++) {
      const coef = dataBytes[i] ^ res[0];
      res.copyWithin(0, 1);
      res[ecLen - 1] = 0;
      if (coef !== 0) {
        for (let j = 0; j < ecLen; j++) {
          res[j] ^= gfMul(gen[j + 1], coef);
        }
      }
    }
    return res;
  }

  // Version table for EC Level L: [version, totalCodewords, ecCodewordsPerBlock, numBlocks, alignmentCenters]
  const QR_VERSIONS_L = [
    null,
    [1, 26, 7, 1, []],
    [2, 44, 10, 1, [6, 18]],
    [3, 70, 15, 1, [6, 22]],
    [4, 100, 20, 1, [6, 26]],
    [5, 134, 26, 1, [6, 30]],
    [6, 172, 18, 2, [6, 34]],
    [7, 196, 20, 2, [6, 22, 38]],
    [8, 242, 24, 2, [6, 24, 42]],
    [9, 292, 30, 2, [6, 26, 46]],
    [10, 346, 18, 4, [6, 28, 50]],
    [11, 404, 20, 4, [6, 30, 54]],
    [12, 466, 24, 4, [6, 32, 58]],
    [13, 532, 26, 4, [6, 34, 62]],
    [14, 581, 30, 4, [6, 26, 46, 66]]
  ];

  function encodeQRMatrix(text) {
    const bytes = new TextEncoder().encode(String(text || ''));
    let ver = 1;
    for (let v = 1; v < QR_VERSIONS_L.length; v++) {
      const [, totalCw, ecCw, blocks] = QR_VERSIONS_L[v];
      const dataCw = totalCw - ecCw * blocks;
      const headerBits = v >= 10 ? 20 : 12;
      const capBytes = Math.floor((dataCw * 8 - headerBits) / 8);
      if (bytes.length <= capBytes) { ver = v; break; }
      if (v === QR_VERSIONS_L.length - 1) ver = v;
    }

    const [, totalCw, ecPerBlock, numBlocks, alignCenters] = QR_VERSIONS_L[ver];
    const totalDataCw = totalCw - ecPerBlock * numBlocks;

    // Bit buffer
    const bits = [];
    const pushBits = (val, len) => {
      for (let i = len - 1; i >= 0; i--) bits.push((val >>> i) & 1);
    };
    pushBits(0b0100, 4); // Byte mode
    pushBits(bytes.length, ver >= 10 ? 16 : 8);
    for (let i = 0; i < bytes.length; i++) pushBits(bytes[i], 8);
    const maxBits = totalDataCw * 8;
    const termLen = Math.min(4, maxBits - bits.length);
    for (let i = 0; i < termLen; i++) bits.push(0);
    while (bits.length % 8 !== 0) bits.push(0);

    const dataCw = new Uint8Array(totalDataCw);
    for (let i = 0; i < bits.length / 8 && i < totalDataCw; i++) {
      let b = 0;
      for (let j = 0; j < 8; j++) b = (b << 1) | bits[i * 8 + j];
      dataCw[i] = b;
    }
    const pads = [0xEC, 0x11];
    for (let i = Math.floor(bits.length / 8), p = 0; i < totalDataCw; i++, p ^= 1) {
      dataCw[i] = pads[p];
    }

    // Split blocks & interleave
    const baseBlockLen = Math.floor(totalDataCw / numBlocks);
    const extraBlocks = totalDataCw % numBlocks;
    const dataBlocks = [];
    const ecBlocks = [];
    let offset = 0;
    for (let b = 0; b < numBlocks; b++) {
      const len = baseBlockLen + (b >= numBlocks - extraBlocks ? 1 : 0);
      const slice = dataCw.slice(offset, offset + len);
      offset += len;
      dataBlocks.push(slice);
      ecBlocks.push(rsComputeEC(slice, ecPerBlock));
    }

    const finalCodewords = [];
    const maxDataLen = baseBlockLen + (extraBlocks > 0 ? 1 : 0);
    for (let i = 0; i < maxDataLen; i++) {
      for (let b = 0; b < numBlocks; b++) {
        if (i < dataBlocks[b].length) finalCodewords.push(dataBlocks[b][i]);
      }
    }
    for (let i = 0; i < ecPerBlock; i++) {
      for (let b = 0; b < numBlocks; b++) {
        finalCodewords.push(ecBlocks[b][i]);
      }
    }

    const size = ver * 4 + 17;
    const modules = Array.from({ length: size }, () => new Int8Array(size)); // 0=unset, 1=dark, -1=light
    const isFunc = Array.from({ length: size }, () => new Uint8Array(size));

    const setFunc = (r, c, dark) => {
      if (r >= 0 && r < size && c >= 0 && c < size) {
        modules[r][c] = dark ? 1 : -1;
        isFunc[r][c] = 1;
      }
    };

    const drawFinder = (r0, c0) => {
      for (let dr = -1; dr <= 7; dr++) {
        for (let dc = -1; dc <= 7; dc++) {
          const dark = dr >= 0 && dr <= 6 && dc >= 0 && dc <= 6 &&
            (dr === 0 || dr === 6 || dc === 0 || dc === 6 || (dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4));
          setFunc(r0 + dr, c0 + dc, dark);
        }
      }
    };
    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    // Alignment patterns
    for (let i = 0; i < alignCenters.length; i++) {
      for (let j = 0; j < alignCenters.length; j++) {
        const r = alignCenters[i], c = alignCenters[j];
        if (isFunc[r][c]) continue;
        for (let dr = -2; dr <= 2; dr++) {
          for (let dc = -2; dc <= 2; dc++) {
            const dark = Math.max(Math.abs(dr), Math.abs(dc)) !== 1;
            setFunc(r + dr, c + dc, dark);
          }
        }
      }
    }

    // Timing patterns
    for (let i = 8; i < size - 8; i++) {
      if (!isFunc[6][i]) setFunc(6, i, i % 2 === 0);
      if (!isFunc[i][6]) setFunc(i, 6, i % 2 === 0);
    }

    // Reserve format & version info
    for (let i = 0; i < 9; i++) {
      if (!isFunc[8][i]) setFunc(8, i, false);
      if (!isFunc[i][8]) setFunc(i, 8, false);
    }
    for (let i = 0; i < 8; i++) {
      setFunc(8, size - 1 - i, false);
      setFunc(size - 1 - i, 8, false);
    }
    setFunc(size - 8, 8, true); // Dark module

    if (ver >= 7) {
      const verBitsTable = [0,0,0,0,0,0,0,0x07C94,0x085BC,0x09A99,0x0A4D3,0x0BBF6,0x0C762,0x0D847,0x0E60D];
      const vBits = verBitsTable[ver] || 0;
      for (let i = 0; i < 18; i++) {
        const bit = ((vBits >>> i) & 1) === 1;
        const a = Math.floor(i / 3), b = i % 3;
        setFunc(a, size - 11 + b, bit);
        setFunc(size - 11 + b, a, bit);
      }
    }

    // Place data bits (mask 0: (r + c) % 2 === 0)
    let bitIdx = 0;
    const totalBits = finalCodewords.length * 8;
    let upward = true;
    for (let right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (let vert = 0; vert < size; vert++) {
        const r = upward ? (size - 1 - vert) : vert;
        for (let j = 0; j < 2; j++) {
          const c = right - j;
          if (!isFunc[r][c]) {
            let dark = false;
            if (bitIdx < totalBits) {
              dark = ((finalCodewords[bitIdx >>> 3] >>> (7 - (bitIdx & 7))) & 1) === 1;
              bitIdx++;
            }
            if ((r + c) % 2 === 0) dark = !dark;
            modules[r][c] = dark ? 1 : -1;
          }
        }
      }
      upward = !upward;
    }

    // Format bits for EC Level L (01), Mask 0 (000) -> 0x77C4
    const fmt = 0x77C4;
    for (let i = 0; i <= 5; i++) setFunc(8, i, ((fmt >>> i) & 1) === 1);
    setFunc(8, 7, ((fmt >>> 6) & 1) === 1);
    setFunc(8, 8, ((fmt >>> 7) & 1) === 1);
    setFunc(7, 8, ((fmt >>> 8) & 1) === 1);
    for (let i = 9; i < 15; i++) setFunc(14 - i, 8, ((fmt >>> i) & 1) === 1);
    for (let i = 0; i < 8; i++) setFunc(size - 1 - i, 8, ((fmt >>> i) & 1) === 1);
    for (let i = 8; i < 15; i++) setFunc(8, size - 15 + i, ((fmt >>> i) & 1) === 1);

    return { size, modules };
  }

  function QRCode(el, opts) {
    const container = typeof el === 'string' ? document.getElementById(el) : el;
    if (!container) return;
    const cfg = typeof opts === 'string' ? { text: opts } : (opts || {});
    const width = cfg.width || 200;
    const height = cfg.height || 200;
    const { size, modules } = encodeQRMatrix(cfg.text || '');
    const quiet = 2;
    const totalModules = size + quiet * 2;
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = cfg.colorLight || '#ffffff';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = cfg.colorDark || '#000000';
    const cellW = width / totalModules;
    const cellH = height / totalModules;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        if (modules[r][c] === 1) {
          ctx.fillRect(Math.floor((c + quiet) * cellW), Math.floor((r + quiet) * cellH), Math.ceil(cellW), Math.ceil(cellH));
        }
      }
    }
    container.innerHTML = '';
    container.appendChild(canvas);
  }
  QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
  global.QRCode = QRCode;

  /* --- 2. Offline jsQR fallback (supports Android BarcodeDetector + pure JS finder/bit reader) --- */
  global.jsQR = function(data, width, height) {
    try {
      // Pure JS binary grid sampler for standard QR codes uploaded from gallery
      const gray = new Uint8Array(width * height);
      let minL = 255, maxL = 0;
      for (let i = 0, p = 0; i < gray.length; i++, p += 4) {
        const l = (data[p] * 77 + data[p + 1] * 150 + data[p + 2] * 29) >> 8;
        gray[i] = l;
        if (l < minL) minL = l;
        if (l > maxL) maxL = l;
      }
      const thresh = (minL + maxL) >> 1;
      // Locate bounding box of dark modules
      let top = height, bottom = 0, left = width, right = 0;
      for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
          if (gray[y * width + x] < thresh) {
            if (y < top) top = y;
            if (y > bottom) bottom = y;
            if (x < left) left = x;
            if (x > right) right = x;
          }
        }
      }
      if (right <= left || bottom <= top) return null;
      // Measure top-left finder pattern width (7 modules)
      let run = 0;
      for (let x = left; x <= right; x++) {
        if (gray[top * width + x] < thresh) run++;
        else if (run > 0) break;
      }
      if (run < 7) return null;
      const modSize = run / 7;
      const qrSpan = ((right - left + 1) + (bottom - top + 1)) / 2;
      const estMods = Math.round(qrSpan / modSize);
      const ver = Math.max(1, Math.min(20, Math.round((estMods - 17) / 4)));
      const size = ver * 4 + 17;
      const stepX = (right - left + 1) / size;
      const stepY = (bottom - top + 1) / size;

      const grid = Array.from({ length: size }, (_, r) =>
        Array.from({ length: size }, (_, c) => {
          const sx = Math.min(width - 1, Math.floor(left + (c + 0.5) * stepX));
          const sy = Math.min(height - 1, Math.floor(top + (r + 0.5) * stepY));
          return gray[sy * width + sx] < thresh ? 1 : 0;
        })
      );

      // Read format info to get mask pattern
      let fmtBits = 0;
      const coords = [[8,0],[8,1],[8,2],[8,3],[8,4],[8,5],[8,7],[8,8],[7,8],[5,8],[4,8],[3,8],[2,8],[1,8],[0,8]];
      for (let i = 0; i < 15; i++) {
        fmtBits |= (grid[coords[i][0]][coords[i][1]] << i);
      }
      fmtBits ^= 0x5412;
      const maskPat = (fmtBits >> 10) & 0x7;
      const maskFn = [
        (r, c) => (r + c) % 2 === 0,
        (r, c) => r % 2 === 0,
        (r, c) => c % 3 === 0,
        (r, c) => (r + c) % 3 === 0,
        (r, c) => (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0,
        (r, c) => ((r * c) % 2 + (r * c) % 3) === 0,
        (r, c) => (((r * c) % 2 + (r * c) % 3) % 2) === 0,
        (r, c) => (((r + c) % 2 + (r * c) % 3) % 2) === 0
      ][maskPat] || ((r, c) => (r + c) % 2 === 0);

      const isReserved = (r, c) => {
        if (r < 9 && c < 9) return true;
        if (r < 9 && c >= size - 8) return true;
        if (r >= size - 8 && c < 9) return true;
        if (r === 6 || c === 6) return true;
        if (ver >= 7 && ((r < 6 && c >= size - 11) || (c < 6 && r >= size - 11))) return true;
        return false;
      };

      const rawBits = [];
      let upward = true;
      for (let rightCol = size - 1; rightCol >= 1; rightCol -= 2) {
        if (rightCol === 6) rightCol = 5;
        for (let v = 0; v < size; v++) {
          const r = upward ? (size - 1 - v) : v;
          for (let j = 0; j < 2; j++) {
            const c = rightCol - j;
            if (!isReserved(r, c)) {
              let bit = grid[r][c];
              if (maskFn(r, c)) bit ^= 1;
              rawBits.push(bit);
            }
          }
        }
        upward = !upward;
      }

      const readInt = (pos, len) => {
        let val = 0;
        for (let i = 0; i < len && pos + i < rawBits.length; i++) val = (val << 1) | rawBits[pos + i];
        return val;
      };
      const mode = readInt(0, 4);
      if (mode !== 4) return null;
      const lenBits = ver >= 10 ? 16 : 8;
      const charCount = readInt(4, lenBits);
      const outBytes = new Uint8Array(charCount);
      for (let i = 0; i < charCount; i++) {
        outBytes[i] = readInt(4 + lenBits + i * 8, 8);
      }
      const decoded = new TextDecoder().decode(outBytes);
      return decoded ? { data: decoded } : null;
    } catch (e) {
      return null;
    }
  };

  /* --- 3. Offline html2canvas (Direct Canvas Capture for Thermal Receipt Area) --- */
  global.html2canvas = async function(el) {
    const innerCanvas = el ? el.querySelector('canvas') : null;
    if (innerCanvas && innerCanvas.width > 0 && innerCanvas.height > 0) {
      const out = document.createElement('canvas');
      out.width = innerCanvas.width + 24;
      out.height = innerCanvas.height + 28;
      const ctx = out.getContext('2d');
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, out.width, out.height);
      ctx.drawImage(innerCanvas, 12, 14);
      return out;
    }
    const fallback = document.createElement('canvas');
    fallback.width = 384;
    fallback.height = 500;
    const ctx = fallback.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, 384, 500);
    return fallback;
  };

  /* --- 4. Pure Offline PDF 1.4 Generator (jsPDF compatible API for Thermal Receipt & A4 Report) --- */
  function JsPDFOffline(opts) {
    const cfg = opts || {};
    const fmt = cfg.format || 'a4';
    const ptPerMm = 72 / 25.4;
    if (Array.isArray(fmt)) {
      this.pageW = Math.round(fmt[0] * ptPerMm);
      this.pageH = Math.round(fmt[1] * ptPerMm);
    } else {
      this.pageW = 595;
      this.pageH = 842;
    }
    this.ptPerMm = ptPerMm;
    this.fontSize = 10;
    this.fontWeight = 'normal';
    this.pages = [[]];
    this.images = [];
  }

  JsPDFOffline.prototype.setFontSize = function(sz) { this.fontSize = sz || 10; };
  JsPDFOffline.prototype.setFont = function(_, weight) { this.fontWeight = weight || 'normal'; };
  JsPDFOffline.prototype.addPage = function() { this.pages.push([]); };

  JsPDFOffline.prototype.text = function(str, xMm, yMm) {
    const clean = String(str || '').replace(/[^\x20-\x7E]/g, ' ').replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
    const x = (xMm * this.ptPerMm).toFixed(2);
    const y = (this.pageH - yMm * this.ptPerMm).toFixed(2);
    const fontKey = this.fontWeight === 'bold' ? '/F2' : '/F1';
    this.pages[this.pages.length - 1].push(`BT ${fontKey} ${this.fontSize} Tf ${x} ${y} Td (${clean}) Tj ET`);
  };

  JsPDFOffline.prototype.line = function(x1Mm, y1Mm, x2Mm, y2Mm) {
    const x1 = (x1Mm * this.ptPerMm).toFixed(2);
    const y1 = (this.pageH - y1Mm * this.ptPerMm).toFixed(2);
    const x2 = (x2Mm * this.ptPerMm).toFixed(2);
    const y2 = (this.pageH - y2Mm * this.ptPerMm).toFixed(2);
    this.pages[this.pages.length - 1].push(`0.6 w ${x1} ${y1} m ${x2} ${y2} l S`);
  };

  JsPDFOffline.prototype.addImage = function(dataUrl, _, xMm, yMm, wMm, hMm) {
    const imgIdx = this.images.length + 1;
    this.images.push({ name: `Im${imgIdx}`, dataUrl });
    const x = (xMm * this.ptPerMm).toFixed(2);
    const y = (this.pageH - (yMm + hMm) * this.ptPerMm).toFixed(2);
    const w = (wMm * this.ptPerMm).toFixed(2);
    const h = (hMm * this.ptPerMm).toFixed(2);
    this.pages[this.pages.length - 1].push(`q ${w} 0 0 ${h} ${x} ${y} cm /Im${imgIdx} Do Q`);
  };

  JsPDFOffline.prototype._buildPdfBytes = function() {
    const encoder = new TextEncoder();
    const chunks = [];
    const offsets = [0];
    let byteLen = 0;
    const pushStr = (s) => {
      const b = encoder.encode(s);
      chunks.push(b);
      byteLen += b.length;
    };
    const pushBytes = (b) => {
      chunks.push(b);
      byteLen += b.length;
    };
    const startObj = (id) => {
      offsets[id] = byteLen;
      pushStr(`${id} 0 obj\n`);
    };

    pushStr('%PDF-1.4\n');
    // 1: Catalog, 2: Pages, 3: Font Regular, 4: Font Bold
    startObj(1); pushStr('<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');
    startObj(3); pushStr('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n');
    startObj(4); pushStr('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>\nendobj\n');

    let nextId = 5;
    const imgObjMap = {};
    for (const img of this.images) {
      // Convert dataUrl to JPEG via offscreen canvas for compact native DCTDecode PDF embedding
      const c = document.createElement('canvas');
      const tmpImg = new Image();
      tmpImg.src = img.dataUrl;
      const w = tmpImg.naturalWidth || 384;
      const h = tmpImg.naturalHeight || 600;
      c.width = w; c.height = h;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h);
      ctx.drawImage(tmpImg, 0, 0, w, h);
      const jpegDataUrl = c.toDataURL('image/jpeg', 0.9);
      const b64 = jpegDataUrl.split(',')[1] || '';
      const bin = atob(b64);
      const jpegBytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) jpegBytes[i] = bin.charCodeAt(i);
      const id = nextId++;
      imgObjMap[img.name] = id;
      startObj(id);
      pushStr(`<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpegBytes.length} >>\nstream\n`);
      pushBytes(jpegBytes);
      pushStr('\nendstream\nendobj\n');
    }

    const pageIds = [];
    const xobjDict = Object.keys(imgObjMap).map(k => `/${k} ${imgObjMap[k]} 0 R`).join(' ');
    for (const ops of this.pages) {
      const contentStr = ops.join('\n') + '\n';
      const contentBytes = encoder.encode(contentStr);
      const contentId = nextId++;
      startObj(contentId);
      pushStr(`<< /Length ${contentBytes.length} >>\nstream\n`);
      pushBytes(contentBytes);
      pushStr('endstream\nendobj\n');

      const pageId = nextId++;
      pageIds.push(pageId);
      startObj(pageId);
      pushStr(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${this.pageW} ${this.pageH}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << ${xobjDict} >> >> /Contents ${contentId} 0 R >>\nendobj\n`);
    }

    startObj(2);
    pushStr(`<< /Type /Pages /Kids [${pageIds.map(id => `${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>\nendobj\n`);

    const xrefStart = byteLen;
    pushStr(`xref\n0 ${nextId}\n0000000000 65535 f \n`);
    for (let i = 1; i < nextId; i++) {
      pushStr(`${String(offsets[i] || 0).padStart(10, '0')} 00000 n \n`);
    }
    pushStr(`trailer\n<< /Size ${nextId} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`);

    const merged = new Uint8Array(byteLen);
    let pos = 0;
    for (const ch of chunks) { merged.set(ch, pos); pos += ch.length; }
    return merged;
  };

  JsPDFOffline.prototype.output = function(type) {
    const bytes = this._buildPdfBytes();
    if (type === 'datauristring') {
      let bin = '';
      for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
      return 'data:application/pdf;base64,' + btoa(bin);
    }
    return bytes;
  };

  JsPDFOffline.prototype.save = function(filename) {
    const blob = new Blob([this._buildPdfBytes()], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename || 'document.pdf';
    document.body.appendChild(a); a.click();
    setTimeout(() => { a.remove(); URL.revokeObjectURL(url); }, 1000);
  };

  global.jspdf = { jsPDF: JsPDFOffline };
})(window);
